// セッションごとのメモ（Claude Code の mod）
//
// 【なぜ要るか】いくつものセッションを並べて使うと、どれが何の作業で次に何をするのかが見えなくなる。
//   着想は zenn の session-memo（yesodco さん・2026-10-06）。コードは借りず自前で書いた。
// 【何をするか】セッションごとに1枚のテキストのメモ。帯の「メモを編集」（または /memo）で Windows のメモ帳が開き、
//   改行も貼り付けも普通に書ける。保存すると、入力欄の上の帯にメモの中身のある先頭の1行が出る（空なら「メモなし」）。
//   /memo <文> と打てば、メモ帳を開かずに1行足せる。同じ作業ディレクトリの前のセッションのメモは「前のメモ」のペインで開ける。
//   mods の Input は1行だけで
//   複数行の指定が無い（2.1.288 の InputProps）ので、書くのはメモ帳に任せた。
// 【保存】メモの実体は ~/.claude/session-memo/<セッション id>.txt（作業ディレクトリには書かない）。
//   どのファイルがどの作業ディレクトリのものかは $.store に、セッションごとに別の鍵（memo-file:<id>）で置く
//   （全セッションが1つの $.store を共有するので、鍵を分けて書き合いを避ける・資料の Save from more than one session）。
//   前の版のメモ（$.store の memo:<id>・作業・次・自由欄）は、初回に見出しつきのテキストにして各セッションの .txt の頭へ写す。
//   前の版の鍵は消さない（読まないだけ）。
// 【線】登録するのは session.start（コマンドの登録）・command.run・ui.render だけ。道具や許可に関わる
//   イベントは登録しない。$.fs.write はメモの置き場の下だけ（memoPath を通したパスだけ）。
//   $.process.spawn は notepad.exe にメモのパスを1つ渡す形だけ（シェルを通さない）。
// 【静的解析の決まり】$ は最上位の関数にだけ渡す・$ の名前空間を変数に入れない・on のイベント名は文字列で書く。

const PANE = 'session-memo-pane'
// 前の版の鍵（読むだけ・消さない）
const OLD_PREFIX = 'memo:'
// セッションごとの「どのファイルか」の鍵
const FILE_PREFIX = 'memo-file:'
// 前の版のメモを写したかの印（全体で1つ）
const MIGRATED_KEY = 'memo-v2-migrated'
// 写したメモの見出し（2回写さないための印にもなる）
const MIGRATED_MARK = '【前の版のメモ】'
// $.store に残す memo-file の数（メモのファイルは消さない。古い索引だけ消す）
const MAX_INDEX = 300
// 1行で書く /memo <文> の長さ
const MAX_LINE = 300
// 帯に出す1行の長さ
const BAND_CHARS = 120
// ペインに出す前のメモの数と、ペインに出すメモの字数
const PAST_SHOWN = 10
const PANE_CHARS = 20000
// 帯を描くたびにセッション id とメモの更新を確かめ直す間隔
const RECHECK_MS = 3000

let memoDir = null
let sessionId = null
let sessionCwd = null
let checkedAt = 0
let memoText = ''
let memoMtime = -1
let past = []
let notice = ''
// メモ帳を開く操作の知らせを出した時刻（帯にはこの後 BAND_NOTICE_MS の間だけ、メモの1行の代わりに出す）
let noticeAt = 0
const BAND_NOTICE_MS = 20000

function messageOf(err) {
  return String((err && err.message) || err)
}

// 比べるための形（/ 区切り・末尾の / なし・小文字。Windows は大小を区別しない）
function comparable(path) {
  return String(path || '').replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()
}

function two(n) {
  return n < 10 ? '0' + n : String(n)
}

// 10/07 21:40 の形（この PC の時計の時刻）
function stamp(ms) {
  const d = new Date(ms)
  return two(d.getMonth() + 1) + '/' + two(d.getDate()) + ' ' + two(d.getHours()) + ':' + two(d.getMinutes())
}

// 中身のある先頭の1行（無ければ ''）
function firstLine(text) {
  for (const line of String(text || '').split(/\r?\n/)) {
    if (line.trim()) return line.trim()
  }
  return ''
}

// メモの置き場（~/.claude/session-memo）。家のフォルダが分からなければ null
async function ensureDir($) {
  if (memoDir) return memoDir
  const home = (await $.env.get('USERPROFILE')) || (await $.env.get('HOME')) || ''
  if (!home) return null
  const sep = home.includes('\\') ? '\\' : '/'
  memoDir = home.replace(/[\\/]+$/, '') + sep + '.claude' + sep + 'session-memo'
  return memoDir
}

// セッション id からメモのパス。id が英数字・-・_ でなければ断る（置き場の外へ出さない）
function memoPath(id) {
  if (!memoDir) throw new Error('メモの置き場が決まっていません')
  if (!/^[A-Za-z0-9_-]{1,80}$/.test(String(id))) throw new Error('セッション id の形が想定外です: ' + id)
  const sep = memoDir.includes('\\') ? '\\' : '/'
  return memoDir + sep + id + '.txt'
}

// メモのファイルを読む（無ければ ''）
async function readFile($, id) {
  try {
    return String(await $.fs.read(memoPath(id)))
  } catch (err) {
    return ''
  }
}

// いまのセッションのメモを読み直す（id が替わったか、ファイルの更新時刻が変わったときだけ）
async function ensureSession($, force) {
  const now = Date.now()
  if (!force && sessionId && now - checkedAt < RECHECK_MS) return
  checkedAt = now
  if (!(await ensureDir($))) {
    // 押した直後の知らせ（段つき）は帯を描き直しても消さない
    if (!(noticeAt && Date.now() - noticeAt < BAND_NOTICE_MS)) notice = '家のフォルダが分からないのでメモを置けません'
    return
  }
  const id = await $.session.id()
  if (id !== sessionId) {
    sessionId = id
    sessionCwd = await $.session.cwd()
    memoMtime = -1
    notice = ''
    await loadPast($)
  }
  let mtime = 0
  try {
    mtime = (await $.fs.stat(memoPath(sessionId))).mtimeMs || 0
  } catch (err) {
    mtime = 0
  }
  if (force || mtime !== memoMtime) {
    memoText = mtime ? await readFile($, sessionId) : ''
    memoMtime = mtime
  }
}

// このセッションのメモがどの作業ディレクトリのものかを残す（前のメモの一覧に使う）
async function touchIndex($) {
  await $.store.set(FILE_PREFIX + sessionId, { cwd: sessionCwd, updatedAt: Date.now() })
  const keys = (await $.store.keys()).filter((key) => key.startsWith(FILE_PREFIX))
  if (keys.length <= MAX_INDEX) return
  const rows = []
  for (const key of keys) {
    const saved = await $.store.get(key)
    rows.push({ key, at: (saved && Number(saved.updatedAt)) || 0 })
  }
  rows.sort((a, b) => a.at - b.at)
  for (const row of rows.slice(0, rows.length - MAX_INDEX)) {
    if (row.key !== FILE_PREFIX + sessionId) await $.store.delete(row.key)
  }
}

// 同じ作業ディレクトリの、ほかのセッションのメモ（新しい順・中身のあるものだけ）
async function loadPast($) {
  const here = comparable(sessionCwd)
  const rows = []
  for (const key of await $.store.keys()) {
    if (!key.startsWith(FILE_PREFIX) || key === FILE_PREFIX + sessionId) continue
    const saved = await $.store.get(key)
    if (!saved || comparable(saved.cwd) !== here) continue
    rows.push({ id: key.slice(FILE_PREFIX.length), updatedAt: Number(saved.updatedAt) || 0 })
  }
  rows.sort((a, b) => b.updatedAt - a.updatedAt)
  past = []
  for (const row of rows) {
    if (past.length >= PAST_SHOWN) break
    const text = await readFile($, row.id)
    if (text.trim()) past.push({ ...row, head: firstLine(text) })
  }
}

// メモを書く（置き場の下の、このセッションのファイルだけ）
async function writeMemo($, text) {
  await $.fs.write(memoPath(sessionId), text)
  memoText = text
  memoMtime = -1
  await touchIndex($)
}

// メモ帳を起こす。$.process.spawn は Promise ではなく async iterable を返し、子は最初の読み出しで起動し
// （起動できなければそこで reject）、ループを抜けると殺される（index.d.ts の $.process.spawn）。
// 閉じるまで待たないよう、ループは裏で回し続けて待たない。ループはモジュールと一緒に終わるので、
// セッションを閉じるとメモ帳も閉じることがある（保存してから閉じるよう知らせる）
function runNotepad($, id) {
  void (async () => {
    try {
      // メモ帳は何も書かない。書いたとしても読み捨てる（読まずに溜めると子が止まる）
      for await (const piece of $.process.spawn({ argv: ['notepad.exe', memoPath(id)] })) void piece
    } catch (err) {
      failAt($, '起動', messageOf(err))
    }
  })()
}

// メモ帳を開けなかったことを、どの段で止まったか（家のフォルダ・セッション・書き込み・起動）つきで必ず知らせる。
//   黙って戻る道があると、押した人に止まった場所が分からない。どの道でも toast・notice に段を書く
function failAt($, stage, detail) {
  notice = 'メモ帳を開けませんでした（' + stage + '）: ' + detail
  noticeAt = Date.now()
  $.ui.toast('メモ帳を開けませんでした（' + stage + '）')
  $.ui.invalidate('ui.render')
}

// メモ帳で開く（無ければ空のファイルを作ってから。メモ帳は「作りますか」と聞かずに開ける）
async function openNotepad($, id) {
  try {
    if (!(await $.fs.exists(memoPath(id)))) await $.fs.write(memoPath(id), '')
    if (id === sessionId) await touchIndex($)
  } catch (err) {
    failAt($, '書き込み', messageOf(err))
    return
  }
  runNotepad($, id)
  // spawn は起動できたことを知らせない（メモ帳は何も書かない）ので、出てこないときの逃げ道も書く
  notice = 'メモ帳を起こしました。保存すると帯に出ます（出てこなければ /memo <文> で1行ずつ足せます）'
  noticeAt = Date.now()
  $.ui.toast('メモ帳を起こしました。書いたら保存してください（セッションを閉じるとメモ帳も閉じることがあります）')
  $.ui.invalidate('ui.render')
}

async function editMemo($) {
  // 押下が届いたことを先に見せる（届いていないのか、途中で止まったのかを見分けるため）
  notice = 'メモ帳を開いています…'
  noticeAt = Date.now()
  $.ui.invalidate('ui.render')
  try {
    if (!(await ensureDir($))) return failAt($, '家のフォルダ', 'USERPROFILE も HOME も取れません')
  } catch (err) {
    return failAt($, '家のフォルダ', messageOf(err))
  }
  try {
    await ensureSession($, true)
  } catch (err) {
    return failAt($, 'セッション', messageOf(err))
  }
  if (!sessionId) return failAt($, 'セッション', 'セッション id が取れません')
  await openNotepad($, sessionId)
}

async function openPane($) {
  await ensureSession($, true)
  await loadPast($)
  return $.ui.open({ id: PANE, title: 'メモ', focus: true, closeOnEscape: true })
}

// 前の版のメモ1件を、見出しつきのテキストにする
function oldMemoText(saved) {
  const lines = [MIGRATED_MARK + (saved.updatedAt ? '（' + stamp(Number(saved.updatedAt)) + ' に書いたもの）' : '')]
  if (typeof saved.task === 'string' && saved.task) lines.push('作業: ' + saved.task)
  const next = Array.isArray(saved.next) ? saved.next.filter((line) => typeof line === 'string' && line) : []
  if (next.length) {
    lines.push('次にやること:')
    for (const line of next) lines.push('- ' + line)
  }
  const free = Array.isArray(saved.free) ? saved.free.filter((line) => typeof line === 'string') : []
  if (free.some((line) => line.trim())) {
    lines.push('メモ（自由）:')
    for (const line of free) lines.push(line)
  }
  lines.push('（ここまで前の版のメモ）', '')
  return lines.join('\n') + '\n'
}

// 前の版のメモを各セッションの .txt の頭へ写す（初回だけ・見出しが既にあれば写さない）。写した件数を印に残す
async function migrate($) {
  if (await $.store.get(MIGRATED_KEY)) return
  if (!(await ensureDir($))) return
  await $.store.set(MIGRATED_KEY, { count: 0, startedAt: Date.now() })
  let count = 0
  const failed = []
  for (const key of await $.store.keys()) {
    if (!key.startsWith(OLD_PREFIX)) continue
    const id = key.slice(OLD_PREFIX.length)
    const saved = await $.store.get(key)
    if (!saved || typeof saved !== 'object') continue
    try {
      const path = memoPath(id)
      const now = (await $.fs.exists(path)) ? String(await $.fs.read(path)) : ''
      if (now.includes(MIGRATED_MARK)) continue
      await $.fs.write(memoPath(id), oldMemoText(saved) + now)
      await $.store.set(FILE_PREFIX + id, { cwd: saved.cwd || '', updatedAt: Number(saved.updatedAt) || 0 })
      count += 1
    } catch (err) {
      failed.push(id)
    }
  }
  await $.store.set(MIGRATED_KEY, { count, failed, finishedAt: Date.now() })
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'memo',
      description: 'このセッションのメモをメモ帳で開く。/memo <文> で1行足す',
      argumentHint: '[足す1行]',
      immediate: true,
    })
    sessionId = null
    try {
      await migrate($)
    } catch (err) {
      notice = '前の版のメモを写せませんでした: ' + messageOf(err)
    }
    return next(e)
  })

  on('command.run', { command: 'memo' }, async ($, e) => {
    const line = String(e.args || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, MAX_LINE)
    if (line) {
      await ensureSession($, true)
      if (!sessionId) return { text: notice }
      try {
        const now = await readFile($, sessionId)
        await writeMemo($, now + (now && !now.endsWith('\n') ? '\n' : '') + line + '\n')
      } catch (err) {
        return { text: 'メモに書けませんでした: ' + messageOf(err) }
      }
      $.ui.invalidate('ui.render')
      return { text: 'メモに1行足しました: ' + line }
    }
    await editMemo($)
    return { text: notice }
  })

  // 入力欄の上の帯。メモの先頭の1行と「メモを編集」。後の mod の帯は同じ行の右に置く
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    await ensureSession($, false)
    const theirs = await next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const head = firstLine(memoText)
    // メモ帳を開く操作の直後は、どこまで進んだか（開いています…・起こしました・どの段で止まったか）を帯に出す。
    //   toast を見落としても、押した結果が帯に残る
    const recent = notice && noticeAt && Date.now() - noticeAt < BAND_NOTICE_MS
    const summary = recent
      ? Text({ dimColor: true, wrap: 'truncate-end', children: [notice] })
      : head
        ? Text({ wrap: 'truncate-end', children: ['📝 ' + head.slice(0, BAND_CHARS)] })
        : Text({ dimColor: true, wrap: 'truncate-end', children: ['メモなし'] })
    // 前のメモは、いまのメモが空で、同じフォルダに前のメモがあるときだけ入口を出す（帯を広げない）
    const pastButton =
      !head && past.length
        ? [Button({ key: 'memo-past', label: '前のメモ', plain: true, dimColor: true, onPress: () => openPane($) })]
        : []
    // 後の mod の帯（file-browser の「ファイル一覧」）は、帯が2段に膨らまないよう同じ行の右に置く。
    return Box({
      flexDirection: 'row',
      columnGap: 2,
      children: [
        Box({ flexDirection: 'column', flexGrow: 1, children: [summary] }),
        Button({ key: 'memo-edit', label: 'メモを編集', plain: true, dimColor: true, onPress: () => editMemo($) }),
        ...pastButton,
        ...(theirs ? [theirs] : []),
      ],
    })
  })

  // メモのペイン（いまのメモの全文と、同じフォルダの前のメモ）
  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const body = memoText.trim()
      ? memoText
          .slice(0, PANE_CHARS)
          .split(/\r?\n/)
          .map((line) => Text({ wrap: 'wrap', children: [line || ' '] }))
      : [Text({ dimColor: true, children: ['（まだ何も書いていません）'] })]
    const pastRows = past.length
      ? past.map((item) =>
          Box({
            key: 'memo-past-' + item.id,
            flexDirection: 'row',
            columnGap: 2,
            children: [
              Text({ dimColor: true, children: [stamp(item.updatedAt)] }),
              Box({ flexGrow: 1, children: [Text({ wrap: 'truncate-end', children: [item.head] })] }),
              Button({ key: 'memo-open-' + item.id, label: '開く', plain: true, dimColor: true, onPress: () => openNotepad($, item.id) }),
            ],
          }),
        )
      : [Text({ dimColor: true, children: ['（同じフォルダの前のメモはありません）'] })]
    return Box({
      flexDirection: 'column',
      children: [
        Box({
          flexDirection: 'row',
          columnGap: 2,
          children: [
            Text({ bold: true, children: ['このセッションのメモ'] }),
            Button({ key: 'memo-notepad', label: 'メモ帳で開く', plain: true, onPress: () => editMemo($) }),
            Button({
              key: 'memo-reload',
              label: '読み直す',
              plain: true,
              dimColor: true,
              onPress: async () => {
                await ensureSession($, true)
                $.ui.invalidate('ui.render')
              },
            }),
          ],
        }),
        ...body,
        ...(notice ? [Text({ dimColor: true, children: [notice] })] : []),
        Text({ children: [' '] }),
        Text({ bold: true, children: ['同じフォルダの前のメモ（開くとメモ帳で開きます）'] }),
        ...pastRows,
      ],
    })
  })
}

